action.command:
node -e "
const fs = require('fs');
const file = process.env.KIRO_FILE_PATH || 'lib/operators.ts';
const src = fs.readFileSync(file, 'utf8');
const EMERGENCY = ['10111','10177','107','112','911','999'];
const numberMatches = src.match(/number:\s*['\"]([0-9]+)['\"]/g) || [];
const numbers = numberMatches.map(m => m.match(/[0-9]+/)[0]);
const bad = numbers.filter(n => EMERGENCY.includes(n));
if (bad.length) { console.error('SAFETY: operator uses emergency number: ' + bad.join(', ')); process.exit(2); }
console.log('Operator safety check passed. Numbers: ' + numbers.join(', '));
"
